def mod10(sayi):
    rakamlar = str(sayi)[::-1]
    tekler = rakamlar[0::2][::-1]
    ciftler = rakamlar[1::2][::-1]
    birlesik = ciftler + str(int(tekler) * 2)
    toplam = sum(int(r) for r in birlesik)
    return (10 - toplam % 10) % 10

def dogrula(kod):
    govde, kontrol = kod.split("-")
    return mod10(govde) == int(kontrol)

for s in ["12345", "98760", "4021"]:
    print(s, mod10(s))
