from math import log2

alanlar = {
    "soyad":  (0.95, 0.01),
    "ad":     (0.90, 0.05),
    "dogum":  (0.97, 0.003),
    "cinsiyet": (0.98, 0.50),
    "il":     (0.85, 0.10),
}
UST, ALT = 12.0, 4.0

def agirlik(alan, uyusuyor):
    m, u = alanlar[alan]
    if uyusuyor:
        return log2(m / u)
    return log2((1 - m) / (1 - u))

def puanla(a, b):
    toplam = 0.0
    for alan in alanlar:
        toplam += agirlik(alan, a[alan] == b[alan])
    return toplam

def karar(puan):
    if puan >= UST:
        return "eslesme"
    if puan <= ALT:
        return "eslesmeme"
    return "inceleme"

